package com.example.rokidgeminisecretary;
import org.json.*;
/** Strict allowlist. Never copies messages, IDs, names, addresses, URLs, keys, or raw errors. */
final class PublicDiagnosticReport {
 static JSONObject build(JSONObject data)throws Exception{JSONObject out=new JSONObject().put("schema",1).put("glassStateFresh",data.optBoolean("transferStateFresh"));for(String name:new String[]{"phoneHealth","glassHealth"}){JSONObject h=data.optJSONObject(name);out.put(name,LocalHealthCheck.publicSummary(h==null?new JSONObject():h));}JSONObject conversation=data.optJSONObject("conversation");if(conversation!=null){JSONObject safe=ConversationDeliveryState.safe(conversation);safe.remove("id");safe.remove("at");out.put("conversation",safe);}JSONObject counts=new JSONObject();JSONArray cards=data.optJSONArray("cards");if(cards!=null)for(int i=0;i<Math.min(100,cards.length());i++){JSONObject c=cards.optJSONObject(i);if(c==null)continue;String phase=c.optString("phase");if(phase.matches("queued|received|running|confirmation|deferred|completed|failed|cancelled|needs_check"))counts.put(phase,counts.optInt(phase)+1);}out.put("requestStateCounts",counts);JSONArray transfers=new JSONArray(),raw=data.optJSONArray("transfers");if(raw!=null)for(int i=0;i<Math.min(2,raw.length());i++){JSONObject t=raw.optJSONObject(i);if(t==null)continue;String kind=t.optString("kind"),phase=t.optString("phase");if(!kind.matches("photo|meeting")||!phase.matches("RUNNING|COMPLETED|PARTIAL|FAILED|INTERRUPTED|UNKNOWN"))continue;JSONObject safe=new JSONObject().put("kind",kind).put("phase",phase);for(String key:new String[]{"expected","confirmed","retained","failed","deferred","unitsExpected","unitsConfirmed"})safe.put(key,Math.max(0,Math.min(720000,t.optLong(key))));transfers.put(safe);}out.put("transfers",transfers);JSONArray issues=new JSONArray(),source=data.optJSONArray("issues");if(source!=null)for(int i=0;i<Math.min(20,source.length());i++)if(source.optString(i).matches("conversation_records|meeting_state|inbox_records|runtime_state|storage_inventory"))issues.put(source.getString(i));return out.put("recordIssues",issues);}
 private PublicDiagnosticReport(){}
}
